export interface ResearchCompany {
  name: string
  code?: string
  industry: string
  seg?: string
  listed?: boolean
  round?: string
  cap?: number | string | null
  pe?: number | string | null
  rev?: number | string | null
  revGrowth?: number | string | null
  gross?: number | string | null
  rd?: number | string | null
  valuation?: number | string | null
  lastFunding?: string
  latest?: string
  latestTech?: string
  desc?: string
  tech?: { date: string; title: string; kind?: string; desc?: string }[]
  funding?: { date: string; round: string; amount?: string; investors?: string; inv?: string | string[] }[]
  /**
   * 融资机构的结构化视图（用于机构维度统计，如「某机构在半导体投了多少家」）。
   * 与 funding 是同一批事实的两种表示：funding 面向人读（原始披露口径），
   * investorsStructured 面向机器聚合（一条记录 = 机构 × 轮次）。
   * 同一机构在同一轮出现多次时只保留角色权重最高的一条。
   */
  investorsStructured?: {
    /** 机构名（规范化，去掉「等」「投资平台」等虚词） */
    name: string
    /** lead=领投 / follow=跟投 / strategic=战略投资 / other=未标注 */
    role: 'lead' | 'follow' | 'strategic' | 'other'
    /** 所属轮次，如「天使轮」「C+ 轮」 */
    round?: string
    /** 该轮融资日期 YYYY-MM */
    date?: string
    /** 机构类型：vc=风险投资 / pe=私募股权 / gov=国资基金 / cvc=产业资本 / other */
    kind?: 'vc' | 'pe' | 'gov' | 'cvc' | 'other'
    /** 备注，如「老股东追投」「连续 3 轮跟投」 */
    note?: string
  }[]
  /** 人事变动历史（日期倒序） */
  execChanges?: { date: string; event: string }[]
  /** 任职名单：上市企业为董监高，未上市为核心团队 */
  executives?: {
    name: string
    title: string
    /** board=董事会 / management=高级管理层 */
    role?: 'board' | 'management'
    /** 任职起止，如「2026.3–2029.3」 */
    tenure?: string
    /** 履历（默认折叠） */
    bio?: string
    /** 持股，如「4,251 万股 · 1.80%」 */
    shares?: string
  }[]
  spark?: (number | string | null)[]
  market?: string
  /** 国产替代对标备注（国际巨头用） */
  note?: string
  [key: string]: unknown
}

// ── 产业链目录树 ────────────────────────────────────────────────
// 行业 -> 环节 -> 细分（leaf）。细分含 name/desc/companies；local=国产化率：高/中/低。
//
// 环节下允许再插一层「工艺阶段」（仅半导体设备 equipment 使用），
// 于是该环节为 4 级：行业 -> 环节 -> 工艺阶段 -> 设备种类。
// 用 leaves 字段的存在性做运行时判别，其余 17 个环节仍是扁平 leaf 数组，
// 对调用方透明（统一走 treeLeaves() 取全部 leaf）。
export interface TreeLeaf {
  name: string
  desc?: string
  detail?: string
  companies?: string[]
  local?: '高' | '中' | '低'
  /** 资本关注热度：一级市场融资热度 + 二级市场估值热度，各 0-100 */
  capital?: {
    /** 一级市场融资热度 0-100 */
    primary: number
    /** 二级市场估值热度 0-100 */
    secondary: number
    /** 一级市场资金动向说明 */
    primaryNote?: string
    /** 二级市场估值说明 */
    secondaryNote?: string
    /** 近 12-18 个月具体融资/IPO/并购事件 */
    events?: string[]
    /** 当前资本最关注的细分方向 */
    hotspots?: string
  }
}

/** 工艺阶段：环节与细分之间的中间层，id 用 slug 以便进 URL */
export interface TreeStage {
  id: string
  name: string
  desc?: string
  leaves: TreeLeaf[]
}

export type TreeValue = TreeLeaf[] | TreeStage[]

/** 运行时不变量判别：该环节是否带「工艺阶段」中间层 */
export function isGrouped(v: TreeValue | undefined): v is TreeStage[] {
  return !!v && v.length > 0 && 'leaves' in (v[0] as TreeStage)
}

/** 取某环节下的全部细分 leaf（分组环节自动展平各阶段） */
export function treeLeaves(seg: string): TreeLeaf[] {
  const v = TREE[seg]
  if (!v) return []
  return isGrouped(v) ? v.flatMap(s => s.leaves) : (v as TreeLeaf[])
}

